package com.aoo.bcg.common.concurrency;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;
class LockOrderGuardTest{@Test void acceptsCanonicalOrderAndRejectsInversionAndSameLevelKeyRegression(){try(var club=LockOrderGuard.enter(LockOrderGuard.Level.CLUB,"10");var room=LockOrderGuard.enter(LockOrderGuard.Level.ROOM,"20");var player=LockOrderGuard.enter(LockOrderGuard.Level.PLAYER,"30");var asset=LockOrderGuard.enter(LockOrderGuard.Level.ASSET,"40");var db=LockOrderGuard.enter(LockOrderGuard.Level.DATABASE,"primary")){}try(var room=LockOrderGuard.enter(LockOrderGuard.Level.ROOM,"20")){assertThrows(IllegalStateException.class,()->LockOrderGuard.enter(LockOrderGuard.Level.CLUB,"10"));}try(var first=LockOrderGuard.enter(LockOrderGuard.Level.PLAYER,"100")){assertThrows(IllegalStateException.class,()->LockOrderGuard.enter(LockOrderGuard.Level.PLAYER,"099"));}}}
